local config = {
  ui_story_5050_50500001_1_dialog_content = "<color=#e8d9bb>Generando escena...</color>",
  ui_story_5050_50500001_2_dialog_content = "<color=#e8d9bb>Generando script final...</color>",
  ui_story_5050_50500001_3_dialog_content = "<color=#e8d9bb>Bienvenida a la <color=#FFB400>Simulador de entrenamiento cooperativo</color>.</color>",
  ui_story_5050_50500001_4_dialog_content = "Es difícil de creer, pero este lugar es idéntico al Umbraton real. Incluso los vecinos que pasan por las calles han sido perfectamente simulados.",
  ui_story_5050_50500001_5_dialog_content = "Desafortunadamente, no puedes entablar conversaciones normales con toda la gente del pueblo.",
  ui_story_5050_50500001_6_dialog_content = "Parece que se puede acceder a todos los edificios y podemos buscar objetivos en varias zonas.",
  ui_story_5050_50500001_7_dialog_content = "Pero esto puede reducir nuestra eficiencia, ya que muchos lugares son inútiles para la misión.",
  ui_story_5050_50500001_8_dialog_content = "No hay problema, podemos enviar a 01 y a los demás a buscarnos.",
  ui_story_5050_50500001_9_dialog_content = "Amigos, este no es el momento para bromas ociosas. ¿Permanecer de pie en lugar de tomar medidas inmediatas? Bueno, así no es como hacen las cosas los caballeros.",
  ui_story_5050_50500001_10_dialog_content = "No olvides por qué estamos aquí en este simulador. No importa cuán grande sea su carga de trabajo, debe comenzar en alguna parte.",
  ui_story_5050_50500001_11_dialog_content = "Muy cierto, pero hacer un trabajo inútil también es una pérdida de tiempo. ¿No es este diseño bastante inútil?",
  ui_story_5050_50500001_12_dialog_content = "Yo tampoco sé lo que \"ella\" estaba pensando...",
  ui_story_5050_50500101_1_dialog_content = "<color=#e8d9bb>No hace mucho...</color>",
  ui_story_5050_50500101_2_dialog_content = "¿Qué fue tan importante que sintió que necesitaba llamarnos durante el recreo?",
  ui_story_5050_50500101_3_dialog_content = "Jejeje, echemos un vistazo, ¡todos los equipos están aquí!",
  ui_story_5050_50500101_4_dialog_content = "¿Puedes parar con la risa siniestra? ¡Me estás asustando! Será mejor que esto sea algo importante para que tomes el descanso de todos así.",
  ui_story_5050_50500101_5_dialog_content = "Cálmense todos. De hecho, tengo buenas noticias para todos ustedes.",
  ui_story_5050_50500101_6_dialog_content = "Sé mejor que nadie que el tiempo de descanso es el más preciado de todos, así que lo haré lo más breve posible. Básicamente, he creado una nueva versión de Battle Simulator.",
  ui_story_5050_50500101_7_dialog_content = "el simulador? ¿Quieres que hagamos entrenamiento de combate ahora mismo?",
  ui_story_5050_50500101_8_dialog_content = "¡Eso es todo! Pero esta versión es diferente de los ejercicios de batalla básicos que estabas haciendo antes, ya que el combate es solo una parte.",
  ui_story_5050_50500101_9_dialog_content = "Agregué un juego, quiero decir, diseñé un montón de misiones de exploración de mapas, misiones cooperativas y etapas de rompecabezas.",
  ui_story_5050_50500101_10_dialog_content = "La victoria no siempre se gana a través de la fuerza bruta. El trabajo en equipo y el trabajo intelectual también son muy importantes.",
  ui_story_5050_50500101_11_dialog_content = "En comparación con los simuladores de batalla tradicionales, creo que este simulador de entrenamiento cooperativo tiene el potencial de entrenar de manera integral las habilidades de todos.",
  ui_story_5050_50500101_12_dialog_content = "Es por eso que quería invitar a todos a probarlo. ¡También me ayudarás con las pruebas al mismo tiempo!",
  ui_story_5050_50500101_13_dialog_content = "¿Qué? ¿Aún no lo has probado?",
  ui_story_5050_50500101_14_dialog_content = "Hice algunas pruebas simples por mí mismo, pero necesito que más personas realicen algunas pruebas en profundidad para mí.",
  ui_story_5050_50500101_15_dialog_content = "Tenga la seguridad de que este simulador de entrenamiento no afectará los resultados reales del Ejercicio militar conjunto: ¡es solo una solicitud personal de su parte!",
  ui_story_5050_50500101_16_dialog_content = "Debo admitir que esta es realmente una oportunidad única y, para ser honesto, también necesitamos capacitación adicional.",
  ui_story_5050_50500101_17_dialog_content = "Si esta es realmente una oportunidad para recibir capacitación adicional, no debemos dejarla pasar. Personalmente, no tengo objeción alguna.",
  ui_story_5050_50500101_18_dialog_content = "Si todos están adentro, comencemos a sacar pajitas. Debido a la naturaleza de los acertijos que enfrentará, solo dos equipos pueden ingresar a la vez.",
  ui_story_5050_50500101_19_dialog_content = "<color=#e8d9bb>Todos proceden rápidamente a sacar pajitas para decidir qué equipos irán primero.</color>",
  ui_story_5050_50500101_20_dialog_content = "Déjame ver... Muy bien, Equipo Twilight y Equipo Yingel¡Eres el primero!",
  ui_story_5050_50500101_21_dialog_content = "Jaja, muy agradable. Eso está absolutamente bien para mí.",
  ui_story_5050_50500101_22_dialog_content = "Debería poder aprender mucho entrenando junto a un capitán de caballeros.",
  ui_story_5050_50500101_23_dialog_content = "Entonces, los otros equipos deberían irse por ahora; no querrían ver las respuestas antes de tener la oportunidad de intentarlo por sí mismos, ¿verdad?",
  ui_story_5050_50500101_24_dialog_content = "Sin más preámbulos, ¡comencemos!",
  ui_story_5050_50500101_25_dialog_content = "Este no es un entrenamiento de batalla ordinario. ¿Cuales son las normas?",
  ui_story_5050_50500101_26_dialog_content = "Oh, cierto, casi me olvido de eso... Pero tan pronto como entren, se darán cuenta por ustedes mismos que los mapas esta vez están cambiando constantemente.",
  ui_story_5050_50500101_27_dialog_content = "¿Quieres decir que hay diferentes mapas?",
  ui_story_5050_50500101_28_dialog_content = "He diseñado un total de <color=#FFB400>seis etapas principales</color>, cada uno basado en una región diferente.",
  ui_story_5050_50500101_29_dialog_content = "Todo el mundo tiene que explorar el mapa y completar la etapa. <color=#FFB400>misiones</color>. ¡Tu objetivo es llegar a la meta y reclamar todos los suministros y recompensas!",
  ui_story_5050_50500101_30_dialog_content = "Estarás equipado con un comunicador para esta simulación, lo que te permitirá comunicarte de forma remota.",
  ui_story_5050_50500101_31_dialog_content = "Suena bastante fácil, como un juego.",
  ui_story_5050_50500101_32_dialog_content = "D-No te concentres demasiado en estos pequeños detalles, no será tan simple como te imaginas.",
  ui_story_5050_50500101_33_dialog_content = "Ambos equipos deberán trabajar juntos para operar ciertos mecanismos en áreas especiales. ¡Este será el momento en que se pruebe su capacidad para trabajar juntos!",
  ui_story_5050_50500101_34_dialog_content = "Todo esto todavía me suena un poco ambiguo. Entremos al simulador y echemos un vistazo por nosotros mismos.",
  ui_story_5050_50500101_35_dialog_content = "Correcto, ¡podría hablar de los detalles para siempre! ¡Ven entonces! Después de ingresar allí, explore a su propio ritmo y pronto sabrá todo lo que hay que saber.",
  ui_story_5050_50500101_36_dialog_content = "Dado que se puede acceder a todos los edificios a voluntad, parece que tendremos que visitar cada uno de ellos.",
  ui_story_5050_50500101_37_dialog_content = "¡Ey! ¿Pueden todos oírme?",
  ui_story_5050_50500101_38_dialog_content = "¿Ves los puntos de misión y los puntos de recursos en el mapa? He ajustado estas áreas clave para que le indiquen automáticamente su ubicación.",
  ui_story_5050_50500101_39_dialog_content = "Gronru puede escuchar todo lo que estábamos diciendo?",
  ui_story_5050_50500101_40_dialog_content = "Esto debería aumentar en gran medida la eficiencia, por lo que los otros equipos no tendrán que esperar afuera por mucho tiempo.",
  ui_story_5050_50500101_41_dialog_content = "Gracias.",
  ui_story_5050_50500101_42_dialog_content = "Jeje, ¡realmente no tenía la intención de hacerlo durante el proceso de desarrollo! Vamos, todos, ¡ustedes pueden hacerlo!",
  ui_story_5050_50500101_43_dialog_content = "Comencemos también e intentemos no pasar por alto estas áreas marcadas.",
  ui_story_5050_50500101_44_dialog_content = "Cada una de las habitaciones a las que se puede ingresar es diferente de su contraparte en el Umbraton real, así que ten mucho cuidado.",
  ui_story_5050_50500101_45_dialog_content = "Parece haber una búsqueda especial entre ellos. May el Dios de la Luz te bendiga.",
  ui_story_5050_50500101_46_dialog_content = "Está bien, tengo esto.",
  ui_story_5050_50500101_47_dialog_content = "Muy bien, ¡dejemos que nuestros espíritus se eleven hasta los límites del cielo! ¡Terminemos esto de una sola vez!",
  ui_story_5050_50500102_1_dialog_content = "Creo que estamos a punto de llegar a la siguiente etapa. ¿Todos siguen en plena forma?",
  ui_story_5050_50500102_2_dialog_content = "No hay problemas por aquí.",
  ui_story_5050_50500102_3_dialog_content = "Estamos bien también.",
  ui_story_5050_50500102_4_dialog_content = "Poco a poco me estoy familiarizando con los entresijos de este entrenamiento. Con todos los diferentes tipos de etapas, podrían ser desafiantes.",
  ui_story_5050_50500102_5_dialog_content = "Supongo Gronru diseñó la primera etapa para permitirnos experimentar las reglas. La siguiente etapa puede no ser tan fácil.",
  ui_story_5050_50500102_6_dialog_content = "Estoy de acuerdo.",
  ui_story_5050_50500102_7_dialog_content = "¡Ja ja! Centrémonos en lo que tenemos que hacer, sin importar lo que se nos presente.",
  ui_story_5050_50500102_8_dialog_content = "Así que todos, ¡hacia la siguiente etapa!",
  ui_story_5050_50500201_1_dialog_content = "Esto es... PlayerName¡Es Soroz!",
  ui_story_5050_50500201_2_dialog_content = "No puedo creer que tenga los planos aquí.",
  ui_story_5050_50500201_3_dialog_content = "Gronru es extremadamente competente. Nunca la subestimes.",
  ui_story_5050_50500201_4_dialog_content = "Tenemos un problema.",
  ui_story_5050_50500201_5_dialog_content = "Esta parece ser la sala de control principal, pero la puerta está sellada. Eso significa que no podemos ir directamente a otro lugar en Soroz.",
  ui_story_5050_50500201_6_dialog_content = "No hay forma de que este escenario se limite a una sola habitación. Debería haber algo escondido por aquí, como una pista o algún tipo de mecanismo.",
  ui_story_5050_50500201_7_dialog_content = "Veo. Solo busca el lugar.",
  ui_story_5050_50500201_8_dialog_content = "¿Qué opinas, Yingel?",
  ui_story_5050_50500201_9_dialog_content = "Oh, no pensé que estarías interesado en escuchar mi opinión. La sala de control principal apenas tiene accesorios o muebles, por lo que el único lugar donde se podrían ocultar pistas es en el panel de control.",
  ui_story_5050_50500201_10_dialog_content = "¡Le diste al clavo! Creo que el panel de control también parece bastante sospechoso.",
  ui_story_5050_50500201_11_dialog_content = "Yingel tiene razón, hay una caja mecánica debajo del panel.",
  ui_story_5050_50500201_12_dialog_content = "Sé que esto es solo realidad virtual, pero esta caja es hermosa.",
  ui_story_5050_50500201_13_dialog_content = "No hay ningún lugar para ingresar una contraseña o desbloquearla. ¿Tal vez necesitamos abrirlo a través de algún otro método?",
  ui_story_5050_50500201_14_dialog_content = "Hmm, he visto artículos experimentales similares antes. Tal vez sea controlado por voz.",
  ui_story_5050_50500201_15_dialog_content = "¿Controlado por voz? Eso significa que todavía requiere una contraseña. Axelia, ¿te gustaría probarlo?",
  ui_story_5050_50500201_16_dialog_content = "Hmm... Contraseña, sala de control maestro.",
  ui_story_5050_50500201_17_dialog_content = "Contraseña incorrecta. Inténtalo de nuevo.",
  ui_story_5050_50500201_18_dialog_content = "Contraseña, Soroz.",
  ui_story_5050_50500201_19_dialog_content = "Contraseña incorrecta. Inténtalo de nuevo.",
  ui_story_5050_50500201_20_dialog_content = "Adivinar al azar no parece ser una solución factible. ¿Hay otras pistas en el panel?",
  ui_story_5050_50500201_21_dialog_content = "... Hmm, he encontrado una pista aquí que parece una contraseña.",
  ui_story_5050_50500201_22_dialog_content = "Genial, Leo. Bueno, no perdamos más tiempo...",
  ui_story_5050_50500201_23_dialog_content = "Yingel, tal vez deberías leerlo.",
  ui_story_5050_50500201_24_dialog_content = "¿Mmm? Bien entonces. Déjame echar un vistazo.",
  ui_story_5050_50500201_25_dialog_content = "...",
  ui_story_5050_50500201_26_dialog_content = "Qué pasa, Yingel? Por favor, léalo rápidamente.",
  ui_story_5050_50500201_27_dialog_content = "Cielos, ¿es algo vergonzoso?",
  ui_story_5050_50500201_28_dialog_content = "(¡La búsqueda es todo lo que importa, nada más es importante...!)",
  ui_story_5050_50500201_29_dialog_content = "Contraseña, \"¿Quién es el más fuerte en la tierra? La espectacular doncella brillante y hermosa, Gronru, del mundo del juego! ¡Kira-Kira!\"",
  ui_story_5050_50500201_30_dialog_content = "...",
  ui_story_5050_50500201_31_dialog_content = "...",
  ui_story_5050_50500201_32_dialog_content = "Lo siento de verdad.",
  ui_story_5050_50500201_33_dialog_content = "<color=#e8d9bb>Retumbar-</color>",
  ui_story_5050_50500201_34_dialog_content = "<size=45>¡¿Qué es eso?!</size>",
  ui_story_5050_50500201_35_dialog_content = "¿Es un terremoto?",
  ui_story_5050_50500201_36_dialog_content = "<size=45>¡Mantengan el equilibrio, todos! ¡Aférrate a mí!</size>",
  ui_story_5050_50500201_37_dialog_content = "Comando de desbloqueo activado. Sepárense en sus respectivos equipos a cada lado de la sala. Teletransportarse en quince segundos—",
  ui_story_5050_50500201_38_dialog_content = "¡Uh!",
  ui_story_5050_50500201_39_dialog_content = "Tos...",
  ui_story_5050_50500201_40_dialog_content = "Parece que nos han teletransportado a otra habitación. Si no me equivoco, debería estar en algún lugar similar al salón.",
  ui_story_5050_50500201_41_dialog_content = "¿Cómo es que señorita? Yingel y Axelia no estas aqui?",
  ui_story_5050_50500201_42_dialog_content = "Leo, ¿Puedes oírme?",
  ui_story_5050_50500201_43_dialog_content = "Parece que nos han asignado habitaciones diferentes. ¿Estás bien por ahí?",
  ui_story_5050_50500201_44_dialog_content = "Estamos bien. Entonces, para eso están los comunicadores.",
  ui_story_5050_50500201_45_dialog_content = "Hay algo que debes saber. Si queremos seguir avanzando, parece que necesitaremos su apoyo.",
  ui_story_5050_50500201_46_dialog_content = "¿Es esta la cooperación que mencionó antes?",
  ui_story_5050_50500201_47_dialog_content = "Me temo que sí, completa la misión de tu parte lo antes posible.",
  ui_story_5050_50500201_48_dialog_content = "Hmm, empecemos lo más rápido que podamos.",
  ui_story_5050_50500201_49_dialog_content = "...",
  ui_story_5050_50500201_50_dialog_content = "Qué ocurre, Axelia? ¿Te sientes bien?",
  ui_story_5050_50500201_51_dialog_content = "Está bien, solo tropecé durante la teletransportación. Vamos.",
  ui_story_5050_50500202_1_dialog_content = "Las cosas han ido progresando bastante bien hasta ahora. ¿Estás bien?",
  ui_story_5050_50500202_2_dialog_content = "No te preocupes, estoy p... tos, tos.",
  ui_story_5050_50500202_3_dialog_content = "¿Estás seguro?",
  ui_story_5050_50500202_4_dialog_content = "Zhao, si no te sientes bien, asegúrate de hacérnoslo saber en cualquier momento.",
  ui_story_5050_50500202_5_dialog_content = "Jeje, no soy tan frágil, no te preocupes.",
  ui_story_5050_50500202_6_dialog_content = "Leo, solo necesitamos mantener nuestro ritmo actual. No hay necesidad de apresurarse.",
  ui_story_5050_50500202_7_dialog_content = "Esto es entrenamiento, ¿no? ¿Cómo podemos tratarlo casualmente, especialmente cuando el Equipo Yingel es darlo todo?",
  ui_story_5050_50500202_8_dialog_content = "Sí, y ahora, gracias a ella, ambas partes están trabajando duro para superar este desafío.",
  ui_story_5050_50500202_9_dialog_content = "Muy bien, ya que todo está bien, sigamos avanzando.",
  ui_story_5050_50500203_1_dialog_content = "Deberíamos poder despejar esta etapa pronto.",
  ui_story_5050_50500203_2_dialog_content = "Bien, ya podemos ver la salida.",
  ui_story_5050_50500203_3_dialog_content = "Yingel, ¿cómo están progresando las cosas por tu parte?",
  ui_story_5050_50500203_4_dialog_content = "Las cosas van bien en este momento. Estamos casi en la salida.",
  ui_story_5050_50500203_5_dialog_content = "Gracias a todos ustedes, eso es.",
  ui_story_5050_50500203_6_dialog_content = "La dificultad ha aumentado significativamente en comparación con antes. Incluso los Eclipsites son más fuertes esta vez.",
  ui_story_5050_50500203_7_dialog_content = "¿No es eso lo mejor? Cuando se trata de entrenamiento, los Eclipsites ordinarios ya no son suficientes.",
  ui_story_5050_50500203_8_dialog_content = "Sin embargo, las misiones y los aspectos de recolección de recursos han ido bien hasta ahora, así que sigan así.",
  ui_story_5050_50500203_9_dialog_content = "La siguiente etapa podría ser más desafiante.",
  ui_story_5050_50500204_1_dialog_content = "Hablando de eso, no esperaba encontrar una habitación tan interesante a bordo de Soroz.",
  ui_story_5050_50500204_2_dialog_content = "Bueno, si Caelestite puede vivir en este Coloso e incluso recibir numerosos invitados aquí, no es de extrañar que cuente con instalaciones completas.",
  ui_story_5050_50500204_3_dialog_content = "...",
  ui_story_5050_50500204_4_dialog_content = "Axelia, ¿es mi imaginación, o te has estado sintiendo un poco mal?",
  ui_story_5050_50500204_5_dialog_content = "Estoy bien. Todo está bien.",
  ui_story_5050_50500204_6_dialog_content = "¿Está seguro? Si no se siente bien, háganoslo saber.",
  ui_story_5050_50500204_7_dialog_content = "Estoy seguro de que. Descansé mucho antes de entrar al simulador, y puedo aguantar mucho más de lo que hemos pasado hasta ahora.",
  ui_story_5050_50500204_8_dialog_content = "Centrémonos en la tarea que tenemos entre manos.",
  ui_story_5050_50500204_9_dialog_content = "Si Axelia dice eso, apresurémonos hacia adelante.",
  ui_story_5050_50500204_10_dialog_content = "... Mmm. Sin embargo, no te esfuerces demasiado.",
  ui_story_5050_50500205_1_dialog_content = "La salida de esta etapa debe estar por delante.",
  ui_story_5050_50500205_2_dialog_content = "Anatoli, estás dibujando un mapa?",
  ui_story_5050_50500205_3_dialog_content = "Sí, he hecho un registro completo del terreno actual.",
  ui_story_5050_50500205_4_dialog_content = "Pero esto es solo un hábito personal mío. Me temo que no será de mucha utilidad.",
  ui_story_5050_50500205_5_dialog_content = "En el combate real, es un buen hábito planificar de inmediato rutas de escape alternativas en caso de emergencia.",
  ui_story_5050_50500205_6_dialog_content = "Suspiro...",
  ui_story_5050_50500205_7_dialog_content = "Axelia, tomemos un descanso. No hay necesidad de que nos esforcemos demasiado.",
  ui_story_5050_50500205_8_dialog_content = "Realmente no hay necesidad. El equipo de Leo ya ha pasado a la siguiente etapa. No hay una buena razón por la que debamos estar rezagados detrás de ellos.",
  ui_story_5050_50500205_9_dialog_content = "Además, este es un ejercicio cooperativo, por lo que no deberíamos causar demoras innecesarias.",
  ui_story_5050_50500205_10_dialog_content = "Bueno, si insistes, pasemos a la siguiente etapa.",
  ui_story_5050_50500205_11_dialog_content = "Pero no te fuerces, solo avísame cuando necesites un descanso.",
  ui_story_5050_50500205_12_dialog_content = "Si algo te sucede, afectará nuestro progreso mucho más que tomar un breve descanso.",
  ui_story_5050_50500205_13_dialog_content = "Entendido.",
  ui_story_5050_50500301_1_dialog_content = "¿Es esta la ciudad de Gannon?",
  ui_story_5050_50500301_2_dialog_content = "Realmente extraño este lugar. Ha pasado un tiempo desde que volví a Gannon City.",
  ui_story_5050_50500301_3_dialog_content = "Es vergonzoso, pero he estado dando limosnas por todo el continente durante mucho tiempo y no he visitado mucho la ciudad de Gannon.",
  ui_story_5050_50500301_4_dialog_content = "Me siento igual.",
  ui_story_5050_50500301_5_dialog_content = "Prácticamente crecí aquí, y aunque también he pasado por mucho, todavía ocupa un lugar especial en mi corazón.",
  ui_story_5050_50500301_6_dialog_content = "No pareces estar haciéndolo muy bien. ¿Cómo sobreviviste al entrenamiento en el cuartel de Illumina?",
  ui_story_5050_50500301_7_dialog_content = "Si no fuera por esas experiencias sádicas límite, no sería quien soy hoy. Tos tos...",
  ui_story_5050_50500301_8_dialog_content = "Poco a poco desarrollé mi propio estilo de combate después de haber sido empujado a varios escenarios de batalla.",
  ui_story_5050_50500301_9_dialog_content = "También aprendí a crear estrategias y comandar batallas.",
  ui_story_5050_50500301_10_dialog_content = "Eso es realmente increíble, espero que la luz siempre brille sobre ti.",
  ui_story_5050_50500301_11_dialog_content = "¡Ey! ¡Parece que ustedes están teniendo una gran conversación allí!",
  ui_story_5050_50500301_12_dialog_content = "Solo un consejo amistoso, no habrá segmentos de soporte en esta etapa, por lo que pueden seguir adelante y organizar su estrategia por sí mismos.",
  ui_story_5050_50500301_13_dialog_content = "Entendido.",
  ui_story_5050_50500301_14_dialog_content = "Entonces, sigamos adelante con todas nuestras fuerzas.",
  ui_story_5050_50500302_1_dialog_content = "Tos, tos... Tos, tos, tos...",
  ui_story_5050_50500302_2_dialog_content = "Los Eclipsites eran claramente mucho más fuertes en la batalla en este momento. Tomemos un descanso.",
  ui_story_5050_50500302_3_dialog_content = "... No es necesario que te detengas por mi bien. Estoy bien.",
  ui_story_5050_50500302_4_dialog_content = "No dije que fuera por ti.",
  ui_story_5050_50500302_5_dialog_content = "No necesita ser tan considerado, Capitán. Leo. La tarea que tenemos entre manos es crucial, aunque agradezco su amabilidad. Tos...!",
  ui_story_5050_50500302_6_dialog_content = "Cuando necesites descansar, tratar de superarlo solo será una carga para el resto del equipo.",
  ui_story_5050_50500302_7_dialog_content = "¿Qué quieres decir con eso? ¿Estás tratando de decir que soy una carga?",
  ui_story_5050_50500302_8_dialog_content = "¡Oh! Cálmense todos, por favor.",
  ui_story_5050_50500302_9_dialog_content = "Tus intenciones aquí son todas buenas. Todos somos hijos del Dios de la Luz, así que mantengamos la armonía.",
  ui_story_5050_50500302_10_dialog_content = "...",
  ui_story_5050_50500302_11_dialog_content = "Está bien. Sé que no puedes obligar a otros a actuar en contra de su voluntad. Vamonos.",
  ui_story_5050_50500303_1_dialog_content = "Gracias a Dios, parece que estamos a punto de llegar a la salida.",
  ui_story_5050_50500303_2_dialog_content = "...",
  ui_story_5050_50500303_3_dialog_content = "(Leo tiene una personalidad poderosa, y Zhao ocasionalmente puede volverse bastante sensible debido a su estímulo físico, aunque parece tener los pies en la tierra la mayor parte del tiempo).",
  ui_story_5050_50500303_4_dialog_content = "(El ambiente ha estado un poco tenso desde hace un momento. Espero que estos dos no terminen enfrentándose de frente).",
  ui_story_5050_50500303_5_dialog_content = "Hah, pronto llegaremos al final del desafío. Aunque la dificultad haya aumentado, somos más que capaces de salir triunfantes.",
  ui_story_5050_50500303_6_dialog_content = "Sin embargo, el combate también es una forma de arte, y la victoria no puede ser ganada simplemente por aquellos que cargan ferozmente en la batalla, lanza en mano. Sin alguien detrás de ellos para diseñar una estrategia, la derrota es inevitable.",
  ui_story_5050_50500303_7_dialog_content = "Joseph, Zhao, cooperamos maravillosamente.",
  ui_story_5050_50500303_8_dialog_content = "No hay necesidad de ser demasiado pesimista o autocrítico debido a asuntos que no podemos manejar en este momento.",
  ui_story_5050_50500303_9_dialog_content = "Todavía hay muchas otras cosas que podemos hacer.",
  ui_story_5050_50500303_10_dialog_content = "Bien. Gracias.",
  ui_story_5050_50500303_11_dialog_content = "Reaccioné un poco de forma exagerada, por favor, no insistas demasiado.",
  ui_story_5050_50500303_12_dialog_content = "¿Por qué habría? Todos somos compañeros de equipo aquí, ¿por qué molestarse con asuntos tan insignificantes?",
  ui_story_5050_50500303_13_dialog_content = "No sabemos si habrá nuevos desafíos en la próxima etapa. Tenemos que tener cuidado a medida que avanzamos.",
  ui_story_5050_50500401_1_dialog_content = "¿Ciudad de Gannon?",
  ui_story_5050_50500401_2_dialog_content = "Así parece.",
  ui_story_5050_50500401_3_dialog_content = "Si no recuerdo mal, tú y Axelia Ambos son nativos de Gannon, ¿correcto?",
  ui_story_5050_50500401_4_dialog_content = "Tu inteligencia es tan perfecta como siempre. De hecho, nacimos en Gannon City.",
  ui_story_5050_50500401_5_dialog_content = "Como yo lo hice.",
  ui_story_5050_50500401_6_dialog_content = "Así que los tres deberíamos tener bastante ventaja en este mapa.",
  ui_story_5050_50500401_7_dialog_content = "Sí. Este lugar ciertamente está lleno de muchos recuerdos.",
  ui_story_5050_50500401_8_dialog_content = "Aquí también es donde conocí Yingel y Sean.",
  ui_story_5050_50500401_9_dialog_content = "Aunque la vida era aburrida en ese entonces, todavía se sentía como si fuéramos una pequeña familia.",
  ui_story_5050_50500401_10_dialog_content = "¿Estás preparado para esto? Axelia?",
  ui_story_5050_50500401_11_dialog_content = "No te preocupes. Estoy bien.",
  ui_story_5050_50500401_12_dialog_content = "Vamos entonces. no deberíamos hacer Leo y su equipo esperan demasiado.",
  ui_story_5050_50500401_13_dialog_content = "...",
  ui_story_5050_50500402_1_dialog_content = "¿Aún puedes seguir?",
  ui_story_5050_50500402_2_dialog_content = "Sin problema.",
  ui_story_5050_50500402_3_dialog_content = "... Estaré bien.",
  ui_story_5050_50500402_4_dialog_content = "Las simulaciones de batalla de Eclipsite son bastante estándar, nunca imaginé que esas extrañas misiones serían tan complicadas.",
  ui_story_5050_50500402_5_dialog_content = "He estado observando el lugar desde que entramos y me he dado cuenta de que los puntos de referencia son bastante diferentes de los encuentros de la vida real.",
  ui_story_5050_50500402_6_dialog_content = "Aunque el concepto de misiones, recursos, cooperación, etc. existe en situaciones de combate reales, no tienen una naturaleza mecánica tan rígida.",
  ui_story_5050_50500402_7_dialog_content = "¿Qué quieres decir?",
  ui_story_5050_50500402_8_dialog_content = "En mi opinión personal, Gronru ha copiado e implementado algunos elementos de juego integrales de un determinado videojuego.",
  ui_story_5050_50500402_9_dialog_content = "No me sorprende... Ciertamente suena como algo que ella haría.",
  ui_story_5050_50500402_10_dialog_content = "Y especulo que agregar mecanismos tan complejos al simulador de batalla puede suponer una mayor carga para los cuerpos de los evaluadores.",
  ui_story_5050_50500402_11_dialog_content = "Especialmente probadores con un menor nivel de forma física.",
  ui_story_5050_50500402_12_dialog_content = "Es solo mi teoría, pero ha faltado el rendimiento de Axelia, y creo que es más capaz que esto.",
  ui_story_5050_50500402_13_dialog_content = "Impresionante. Nunca hubiera sido capaz de darme cuenta de eso...",
  ui_story_5050_50500402_14_dialog_content = "Axelia, ¿te gustaría salir del simulador por un rato? No queremos que esta prueba afecte su desempeño en el Ejercicio Militar Conjunto real...",
  ui_story_5050_50500402_15_dialog_content = "No es tan grave como todo eso.",
  ui_story_5050_50500402_16_dialog_content = "No afectará el ejercicio, estoy seguro de eso.",
  ui_story_5050_50500402_17_dialog_content = "Muy bien, entonces, tomemos una decisión rápida y avancemos lo antes posible.",
  ui_story_5050_50500403_1_dialog_content = "Puedo ver la salida.",
  ui_story_5050_50500403_2_dialog_content = "Hemos completado la mayoría de los desafíos y actualmente parece que la cuarta etapa está llegando a su fin.",
  ui_story_5050_50500403_3_dialog_content = "Hemos estado aquí por tanto tiempo. PlayerName y los demás deben estar impacientes esperándonos.",
  ui_story_5050_50500403_4_dialog_content = "No hay nada que podamos hacer al respecto. Aunque solo hay seis etapas, esta prueba me ha llevado mucho más tiempo del que esperaba.",
  ui_story_5050_50500403_5_dialog_content = "También, Vice sabe mucho de mecánica, así que PlayerName y los demás podrían superar estas etapas más rápido que nosotros.",
  ui_story_5050_50500403_6_dialog_content = "Está bien, vamos a ir a nuestro propio ritmo.",
  ui_story_5050_50500403_7_dialog_content = "Perdón por hacer que todos se preocupen por mí todo este tiempo...",
  ui_story_5050_50500403_8_dialog_content = "Todo lo que importa es que estás bien.",
  ui_story_5050_50500403_9_dialog_content = "Tal vez podamos unirnos a ellos en la próxima etapa.",
  ui_story_5050_50500501_1_dialog_content = "Parece que volvimos al tema de Entrañas cogobernado en esta etapa.",
  ui_story_5050_50500501_2_dialog_content = "Yingel, ¿va todo bien por tu parte?",
  ui_story_5050_50500501_3_dialog_content = "Sí, todo es bueno para nosotros.",
  ui_story_5050_50500501_4_dialog_content = "Solo me gustaría confirmar una cosa con ustedes... ¿Alguno de ustedes se siente mal?",
  ui_story_5050_50500501_5_dialog_content = "... ¿Por qué lo preguntas?",
  ui_story_5050_50500501_6_dialog_content = "Axelia se ha estado sintiendo mal todo este tiempo.",
  ui_story_5050_50500501_7_dialog_content = "Sospecho que los mecanismos excesivamente complejos de este simulador imponen una mayor carga a las personas con constituciones físicas débiles.",
  ui_story_5050_50500501_8_dialog_content = "Así que eso es lo que está mal.",
  ui_story_5050_50500501_9_dialog_content = "Hmm, en realidad yo también me había dado cuenta.",
  ui_story_5050_50500501_10_dialog_content = "¡Hola a todos!",
  ui_story_5050_50500501_11_dialog_content = "Lo siento, he estado haciendo una prueba en el simulador, acabo de escuchar tu conversación.",
  ui_story_5050_50500501_12_dialog_content = "Realmente no consideré el efecto físico que el simulador podría tener en sus usuarios...",
  ui_story_5050_50500501_13_dialog_content = "Pero parece que la mayoría de las deducciones de Anatoli son correctas.",
  ui_story_5050_50500501_14_dialog_content = "Este es un tema relativamente importante. Tal vez Zhao y Axelia debe salir y tomar un descanso?",
  ui_story_5050_50500501_15_dialog_content = "No hay necesidad.",
  ui_story_5050_50500501_16_dialog_content = "¿E-Eres realmente tan determinado?",
  ui_story_5050_50500501_17_dialog_content = "Tengo fe en mi cuerpo. Pediré descansar cuando sea necesario.",
  ui_story_5050_50500501_18_dialog_content = "Aquí igual.",
  ui_story_5050_50500501_19_dialog_content = "Nos estamos acercando al final. Terminemos con esto.",
  ui_story_5050_50500501_20_dialog_content = "Si insisten, respetemos las opiniones de las partes involucradas.",
  ui_story_5050_50500501_21_dialog_content = "De acuerdo, también estaré pendiente de la situación de todos en todo momento.",
  ui_story_5050_50500501_22_dialog_content = "Esta etapa parece tener una sección de desbloqueo cooperativo. Leo, contamos contigo.",
  ui_story_5050_50500501_23_dialog_content = "No te preocupes, resolvamos esto de una vez.",
  ui_story_5050_50500502_1_dialog_content = "Parece que este escenario tiene un tema de Entrañas.",
  ui_story_5050_50500502_2_dialog_content = "Parece que necesitaremos Leo y los demás para ayudarnos a desbloquear el camino por delante antes de que podamos pasar.",
  ui_story_5050_50500502_3_dialog_content = "Bien. Tomemos un descanso aquí mientras esperamos.",
  ui_story_5050_50500502_4_dialog_content = "Suspiro...",
  ui_story_5050_50500502_5_dialog_content = "(Axelia parece muy cansado.)",
  ui_story_5050_50500502_6_dialog_content = "(Nunca esperé que el pequeño Aurorian del orfanato hace tantos años fuera a crecer para ser tan fuerte).",
  ui_story_5050_50500502_7_dialog_content = "(Mirando hacia atrás, parece que fue ayer.)",
  ui_story_5050_50500502_8_dialog_content = "... ¿Pensando acerca de algo?",
  ui_story_5050_50500502_9_dialog_content = "Solo recordando el pasado.",
  ui_story_5050_50500502_10_dialog_content = "¿Recuerdos de la infancia?",
  ui_story_5050_50500502_11_dialog_content = "¿Por qué dices eso?",
  ui_story_5050_50500502_12_dialog_content = "No subestimes el alcance de mi red de inteligencia. Usted y Axelia se conocen desde que eran niños. Lo se todo acerca de eso.",
  ui_story_5050_50500502_13_dialog_content = "Sí, nos conocemos desde que éramos muy jóvenes.",
  ui_story_5050_50500502_14_dialog_content = "Pelear junto a un viejo conocido en el que realmente confías es algo envidiable, desde cierta perspectiva.",
  ui_story_5050_50500502_15_dialog_content = "¿Tienes a alguien así?",
  ui_story_5050_50500502_16_dialog_content = "...",
  ui_story_5050_50500502_17_dialog_content = "Dejemos de charlar por ahora, no nos gustaría despertarla.",
  ui_story_5050_50500503_1_dialog_content = "Aunque esto realmente no califica como un entrenamiento de batalla intensivo, esta simulación aún requiere un esfuerzo físico significativo. ¿Estás bien?",
  ui_story_5050_50500503_2_dialog_content = "Estoy bien. ¿Zhao?",
  ui_story_5050_50500503_3_dialog_content = "Yo también estoy bien.",
  ui_story_5050_50500503_4_dialog_content = "<size=45>¡¿?!</size>",
  ui_story_5050_50500503_5_dialog_content = "¿De qué se trata todo esto?",
  ui_story_5050_50500503_6_dialog_content = "¡Ay! ¡Lo siento!",
  ui_story_5050_50500503_7_dialog_content = "Este es un error conocido... A veces, se carga el mapa incorrecto.",
  ui_story_5050_50500503_8_dialog_content = "Pero no te preocupes, ¡no tendrá ningún impacto en tu progreso!",
  ui_story_5050_50500503_9_dialog_content = "Me di cuenta antes de que hay brechas obvias en las conexiones entre algunas habitaciones en los escenarios.",
  ui_story_5050_50500503_10_dialog_content = "Pero no he visto ninguna de estas brechas en los caminos donde puedes encontrar Eclipsites.",
  ui_story_5050_50500503_11_dialog_content = "Supongo que todas esas habitaciones se generaron al azar, ¿correcto?",
  ui_story_5050_50500503_12_dialog_content = "<size=45>¡¡¡!!!</size>",
  ui_story_5050_50500503_13_dialog_content = "¡No intentes adivinar al azar los pensamientos del diseñador!",
  ui_story_5050_50500503_14_dialog_content = "¡Es confidencial! ¡Confidencial!",
  ui_story_5050_50500503_15_dialog_content = "Zhao, tus poderes de observación son extremadamente agudos.",
  ui_story_5050_50500503_16_dialog_content = "Realmente eres digno de tu reputación como el estratega sin igual de Illumina, siendo capaz de captar detalles tan minuciosos.",
  ui_story_5050_50500503_17_dialog_content = "Eso es un poco exagerado. Me he acostumbrado a observar los detalles en el campo de batalla.",
  ui_story_5050_50500503_18_dialog_content = "¡Está bien! No te preocupes por estos pequeños detalles, ¡simplemente pasa a la siguiente etapa rápidamente! ¡La última etapa no será fácil!",
  ui_story_5050_50500503_19_dialog_content = "¡Jeje, todavía no sacará lo mejor de nosotros! ¡Vamos!",
  ui_story_5050_50500504_1_dialog_content = "Parece que estamos a punto de llegar a la etapa final.",
  ui_story_5050_50500504_2_dialog_content = "La etapa final no será fácil... Concéntrense en el juego, todos.",
  ui_story_5050_50500504_3_dialog_content = "Yingel, ¿cómo estás por tu parte? ¿Ya has llegado a la salida?",
  ui_story_5050_50500504_4_dialog_content = "Casi estámos allí.",
  ui_story_5050_50500504_5_dialog_content = "Es Axelia ¿bueno?",
  ui_story_5050_50500504_6_dialog_content = "No te preocupes, acabo de descansar y ahora me siento mucho mejor.",
  ui_story_5050_50500504_7_dialog_content = "Estoy en plena forma y listo para enfrentar el desafío final de frente.",
  ui_story_5050_50500504_8_dialog_content = "Jaja, me alegra escucharlo!",
  ui_story_5050_50500504_9_dialog_content = "¡Nos vemos en la etapa final!",
  ui_story_5050_50500504_10_dialog_content = "Bien, avancemos rápidamente.",
  ui_story_5050_50500601_1_dialog_content = "...",
  ui_story_5050_50500601_2_dialog_content = "Qué ocurre, Leo? ¿Te sientes bien?",
  ui_story_5050_50500601_3_dialog_content = "Nunca nadie me había preguntado eso antes... Tenga la seguridad de que mi fortaleza no conoce límites.",
  ui_story_5050_50500601_4_dialog_content = "Capitán Leo, es porque estamos en Lumopolis?",
  ui_story_5050_50500601_5_dialog_content = "Eres de Lumópolis. Este mapa debe resultarle muy familiar.",
  ui_story_5050_50500601_6_dialog_content = "... Jaja, y nunca antes alguien había adivinado lo que estaba pensando tan fácilmente.",
  ui_story_5050_50500601_7_dialog_content = "Tienes razón, no lo puedo negar, nací aquí.",
  ui_story_5050_50500601_8_dialog_content = "Lumopolis me ha dado mucho, pero también me ha quitado mucho.",
  ui_story_5050_50500601_9_dialog_content = "Un elenco de nobles desterrados de Uptown a un área infinitamente cercana a la Noche Eterna. Incluso si mueres, no eres más que un cadáver podrido, llorado por nadie.",
  ui_story_5050_50500601_10_dialog_content = "Naturalmente, tuve muchas experiencias inolvidables, pero también cambiaron lentamente mi forma de pensar.",
  ui_story_5050_50500601_11_dialog_content = "Leo...",
  ui_story_5050_50500601_12_dialog_content = "...",
  ui_story_5050_50500601_13_dialog_content = "No quise divagar así. Todo lo que necesitas saber es que actualmente solo tengo un objetivo: luchar contra los Eclipsites con todos los que estén dispuestos a estar a mi lado.",
  ui_story_5050_50500601_14_dialog_content = "Podemos hablar de otros asuntos en nuestro tiempo libre cuando tengamos algo de tiempo libre en el futuro.",
  ui_story_5050_50500601_15_dialog_content = "Excelente. Me encantaría escuchar más.",
  ui_story_5050_50500601_16_dialog_content = "Leo, ¿tú también has llegado a Lumopolis por allá?",
  ui_story_5050_50500601_17_dialog_content = "Sí, estamos en el mapa Uptown.",
  ui_story_5050_50500601_18_dialog_content = "Deberíamos encontrarnos cerca del final. Sigan adelante, todos.",
  ui_story_5050_50500601_19_dialog_content = "Tú también. Mantenerse seguro.",
  ui_story_5050_50500601_20_dialog_content = "¡Vamos a mudarnos!",
  ui_story_5050_50500602_1_dialog_content = "¿Esto es... Lumópolis?",
  ui_story_5050_50500602_2_dialog_content = "Nunca he estado aquí antes.",
  ui_story_5050_50500602_3_dialog_content = "A juzgar por el diseño aquí, esto debería ser el Bajo Lumopolis. Sin duda tiene un estilo único.",
  ui_story_5050_50500602_4_dialog_content = "Los tres estamos estacionados en Illumina. No hemos tenido la oportunidad de familiarizarnos con Lumopolis.",
  ui_story_5050_50500602_5_dialog_content = "Deberíamos aprovechar esta oportunidad para echar un vistazo.",
  ui_story_5050_50500602_6_dialog_content = "Lumópolis...",
  ui_story_5050_50500602_7_dialog_content = "Anatoli, tienes algo en contra de Lumopolis?",
  ui_story_5050_50500602_8_dialog_content = "Me considero un centrista en este asunto. Aunque el vínculo entre Illumina y Lumopolis es algo delicado, no me inclino por ninguno de los dos lados.",
  ui_story_5050_50500602_9_dialog_content = "Todos tenemos los mismos objetivos y esperanzas de un mañana mejor. ¿Por qué utilizar tales facciones para sembrar deliberadamente hostilidad y prejuicio?",
  ui_story_5050_50500602_10_dialog_content = "Ese es exactamente el tipo de respuesta que esperaba de usted.",
  ui_story_5050_50500602_11_dialog_content = "No importa de dónde seas o a qué facción pertenezcas, ahora todos tenemos un solo objetivo común.",
  ui_story_5050_50500602_12_dialog_content = "Quizás ocasionalmente mirar un problema desde una perspectiva diferente podría facilitar las cosas.",
  ui_story_5050_50500602_13_dialog_content = "La etapa final, debe ser desafiante.",
  ui_story_5050_50500602_14_dialog_content = "Sí. Me pregunto si habrá algún desafío de etapa especial...",
  ui_story_5050_50500602_15_dialog_content = "¡Vamos!",
  ui_story_5050_50500603_1_dialog_content = "Leo! Por fin estamos juntos de nuevo.",
  ui_story_5050_50500603_2_dialog_content = "Debo admitir que trabajamos muy bien juntos, de lo contrario no habríamos llegado a la meta tan rápido.",
  ui_story_5050_50500603_3_dialog_content = "Pero no entendí muy bien algunas de las misiones. Esos eran dolores de cabeza.",
  ui_story_5050_50500603_4_dialog_content = "Todo fue gracias a los esfuerzos concertados de todos que lo logramos.",
  ui_story_5050_50500603_5_dialog_content = "Axelia, ¿Cómo lo llevas?",
  ui_story_5050_50500603_6_dialog_content = "Me siento al cien por cien.",
  ui_story_5050_50500603_7_dialog_content = "Alabado sea el Dios de la Luz por las bendiciones. Es el poder de nuestra confianza mutua lo que ha hecho que nuestro viaje sea tan exitoso.",
  ui_story_5050_50500603_8_dialog_content = "¡Guau! ¡Buen trabajo! ¡Enhorabuena por llegar a la meta!",
  ui_story_5050_50500603_9_dialog_content = "¿Te gustó el entrenamiento?",
  ui_story_5050_50500603_10_dialog_content = "Puede ser diferente del entrenamiento práctico al que está acostumbrado, pero también ayuda a trabajar en una variedad de habilidades, lo que lo hace igualmente gratificante.",
  ui_story_5050_50500603_11_dialog_content = "Esta fue una experiencia rara para que nos familiarizáramos más con las habilidades de los demás a través de una estrecha cooperación.",
  ui_story_5050_50500603_12_dialog_content = "Jejeje, otro clasico Gronru producción, desarrollada durante varios días y noches de insomnio!",
  ui_story_5050_50500603_13_dialog_content = "Otra pequeña sugerencia: tal vez debería modificar la contraseña controlada por voz en el mapa Colossus.",
  ui_story_5050_50500603_14_dialog_content = "¿Eh? Oh...",
  ui_story_5050_50500603_15_dialog_content = "<size=45>¡¿Qué?!?! ¿No lo cambié?</size>",
  ui_story_5050_50500603_16_dialog_content = "<size=45>¡E-Eso fue solo algo que agregué al azar durante la depuración!</size>",
  ui_story_5050_50500603_17_dialog_content = "Está bien... Solo unos pocos de nosotros conocemos la contraseña en este momento.",
  ui_story_5050_50500603_18_dialog_content = "Y luego solo hay Vice, Carleen, y PlayerName hasta la próxima.",
  ui_story_5050_50500603_19_dialog_content = "No me estás haciendo sentir mejor.",
  ui_story_5050_50500603_20_dialog_content = "Ejem... De todos modos, buen trabajo, todos. No dejes que los equipos restantes esperen demasiado, prepárate...",
  ui_story_5050_50500603_21_dialog_content = "<color=#e8d9bb>Retumbar, retumbar...</color>",
  ui_story_5050_50500603_22_dialog_content = "¿Es eso un terremoto?",
  ui_story_5050_50500603_23_dialog_content = "... ¿Qué está sucediendo? ¡¿Por qué el sistema de repente reportó un error?!",
  ui_story_5050_50500603_24_dialog_content = "¡Cuidado con vuestro paso, todos!",
  ui_story_5050_50500603_25_dialog_content = "<size=45>¡¿?!</size>",
  ui_story_5050_50500603_26_dialog_content = "El mapa está cambiando.",
  ui_story_5050_50500603_27_dialog_content = "Son todas las etapas en las que hemos estado antes. ¿Hay algo mal con el sistema?",
  ui_story_5050_50500603_28_dialog_content = "¡Aaah! Todos, esperen un momento, ¡lo estoy arreglando!",
  ui_story_5050_50500603_29_dialog_content = "<color=#e8d9bb>Minutos después...</color>",
  ui_story_5050_50500603_30_dialog_content = "Uf... Debería estar bien ahora.",
  ui_story_5050_50500603_31_dialog_content = "Lo siento, es posible que hayan quedado algunos errores menores en la última parte.",
  ui_story_5050_50500603_32_dialog_content = "Supongo que no depuré la etapa final lo suficientemente a fondo.",
  ui_story_5050_50500603_33_dialog_content = "¿Esa cosa de adelante también es uno de tus bichos?",
  ui_story_5050_50500603_34_dialog_content = "¿Eh? ¿Qué?",
  ui_story_5050_50500603_35_dialog_content = "<anim type=Shake><size=45>Graah! Graaah!</size></anim>",
  ui_story_5050_50500603_36_dialog_content = "¡¿Q-Qué es eso?! ¡No recuerdo haber agregado algo así a la simulación!",
  ui_story_5050_50500603_37_dialog_content = "No hay más remedio que asumirlo.",
  ui_story_5050_50500603_38_dialog_content = "¡Piense en ello como una sesión de entrenamiento improvisada! ¡Vamos!",
  ui_story_5050_50500604_1_dialog_content = "<size=45>¡Buen trabajo, todos! ¡Felicitaciones por completar la etapa!</size>",
  ui_story_5050_50500604_2_dialog_content = "Ya sabes, superar ese último Eclipsite que acaba de aparecer del cielo azul claro fue mucho más difícil que todas las etapas anteriores.",
  ui_story_5050_50500604_3_dialog_content = "Ja, pero de hecho era una rara oportunidad para un entrenamiento de combate realmente desafiante. Puede que nos enfrentemos a enemigos aún más fuertes en el campo de batalla.",
  ui_story_5050_50500604_4_dialog_content = "En efecto. El error fue más emocionante que las etapas reales.",
  ui_story_5050_50500604_5_dialog_content = "¡N-No puedes decirle ese tipo de cosas a un diseñador!",
  ui_story_5050_50500604_6_dialog_content = "Pero ya sea luchando con los Caballeros Ironthorn o en el Ejercicio Militar Conjunto, la cooperación es esencial para el combate.",
  ui_story_5050_50500604_7_dialog_content = "Una sola persona está limitada en lo que puede lograr. Incluso como líder, luchar solo es como ser un retoño vacilante en la oscuridad.",
  ui_story_5050_50500604_8_dialog_content = "Los compañeros son la luz, el agua y el poder sublime que puede convertir un retoño en un árbol majestuoso.",
  ui_story_5050_50500604_9_dialog_content = "Nuestras victorias se basan en el esfuerzo de cada uno de nuestros compañeros.",
  ui_story_5050_50500604_10_dialog_content = "No todos los días uno llega a escuchar Leo hacer un discurso tan emotivo.",
  ui_story_5050_50500604_11_dialog_content = "Solo estaba expresando mis sentimientos.",
  ui_story_5050_50500604_12_dialog_content = "Cuando se enfrenta a misiones tan complejas, una sola persona es como una mosca sin cabeza sin un equipo que trabaje en conjunto por una causa común.",
  ui_story_5050_50500604_13_dialog_content = "También estoy muy agradecido por la ayuda de todos.",
  ui_story_5050_50500604_14_dialog_content = "Acabo de hacer lo que pensé que era correcto.",
  ui_story_5050_50500604_15_dialog_content = "En este momento, aceptemos esta cálida bondad con paz en nuestros corazones. May el Dios de la Luz bendiga a todos nuestros compañeros de confianza ya nosotros.",
  ui_story_5050_50500604_16_dialog_content = "Entonces, ¿qué juego sirvió de base para esta simulación?",
  ui_story_5050_50500604_17_dialog_content = "En realidad, era Sword of the, quiero decir, ¡la diseñé yo mismo!",
  ui_story_5050_50500604_18_dialog_content = "Oh. Eso es muy impresionante.",
  ui_story_5050_50500604_19_dialog_content = "Pero la próxima vez, deberías pensar en borrar el logo del desarrollador original de los activos del juego.",
  ui_story_5050_50500604_20_dialog_content = "<size=45>¡¡¡!!!</size>",
  ui_story_5050_50500604_21_dialog_content = "¿Descubriste todas las fallas en mi juego? Eres un oficial de inteligencia inteligente.",
  ui_story_5050_50500604_22_dialog_content = "Está bien, no te burles de ella. Esta fue una sesión de entrenamiento muy significativa para todos nosotros.",
  ui_story_5050_50500604_23_dialog_content = "¿Por qué no PlayerName, Beretta, y los demás ya vienen? Deben estar cansados de esperar.",
  ui_story_5050_50500604_24_dialog_content = "Recuerda lo que dije, hay elementos de exploración y resolución de acertijos en este simulador, por lo que es mejor si dejamos que eviten posibles spoilers.",
  ui_story_5050_50500604_25_dialog_content = "Sin embargo, no hubo demasiados problemas del sistema durante el proceso de prueba, ¡así que diría que fue bastante exitoso!",
  ui_story_5050_50500604_26_dialog_content = "Entonces, dejemos PlayerName ¡y los demás lo experimentan todo por sí mismos!",
  ui_story_5050_50500604_27_dialog_content = "Leo, Yingel¡Ve y diles que entren!"
}
